1	import { useState, type FormEvent } from 'react';
2	import { ROTULO_TIPO_CONTA, TIPOS_CONTA, type DadosConta } from '../domain/contas';
3	import { parseValor, valorParaCampo } from '../domain/money';
4	import type { Conta, Resultado, TipoConta } from '../domain/types';
