13	export function ContaForm({ inicial, onSalvar, onCancelar }: Props) {
14	  const [nome, setNome] = useState(inicial?.nome ?? '');
15	  const [tipo, setTipo] = useState<TipoConta>(inicial?.tipo ?? 'corrente');
16	  const [saldo, setSaldo] = useState(inicial ? valorParaCampo(inicial.saldoInicial) : '');
17	  const [fechamento, setFechamento] = useState(inicial?.cartao ? String(inicial.cartao.diaFechamento) : '');
18	  const [vencimento, setVencimento] = useState(inicial?.cartao ? String(inicial.cartao.diaVencimento) : '');
19	  const [limite, setLimite] = useState(inicial?.cartao ? valorParaCampo(inicial.cartao.limite) : '');
20	  const [erros, setErros] = useState<Record<'nome' | 'saldo' | 'geral' | 'diaFechamento' | 'diaVencimento' | 'limite', string | undefined>>({
21	    nome: undefined, saldo: undefined, geral: undefined, diaFechamento: undefined, diaVencimento: undefined, limite: undefined,
22	  });
23	  const semErros = { nome: undefined, saldo: undefined, geral: undefined, diaFechamento: undefined, diaVencimento: undefined, limite: undefined };
24	
25	  const enviar = (e: FormEvent) => {
26	    e.preventDefault();
27	    const saldoInicial = saldo.trim() === '' ? 0 : parseValor(saldo);
28	    if (saldoInicial === null) {
29	      setErros({ ...semErros, saldo: 'Informe um valor válido, como 1.234,56 ou -50,00.' });
30	      return;
31	    }
32	    // Ciclo do cartão é tudo ou nada: se qualquer campo foi preenchido, todos são validados.
33	    const preencheuCartao = tipo === 'cartao' && [fechamento, vencimento, limite].some((v) => v.trim() !== '');
34	    const limiteCentavos = parseValor(limite);
35	    const cartao = preencheuCartao
36	      ? { diaFechamento: Number(fechamento), diaVencimento: Number(vencimento), limite: limiteCentavos ?? Number.NaN }
37	      : undefined;
38	    const r = onSalvar({ nome, tipo, saldoInicial, cartao });
39	    if (!r.ok) {
40	      const campo = r.campo as keyof typeof semErros | undefined;
41	      setErros(campo && campo in semErros ? { ...semErros, [campo]: r.erro } : { ...semErros, geral: r.erro });
42	    }
43	  };
44	
45	  return (
46	    <form onSubmit={enviar} noValidate className="grid gap-3 sm:grid-cols-3" aria-label={inicial ? 'Editar conta' : 'Nova conta'}>
47	      <CampoTexto label="Nome" value={nome} onChange={(e) => setNome(e.target.value)} erro={erros.nome} maxLength={80} autoComplete="off" />
48	      <CampoSelect label="Tipo" value={tipo} onChange={(e) => setTipo(e.target.value as TipoConta)}>
49	        {TIPOS_CONTA.map((t) => (
50	          <option key={t} value={t}>
51	            {ROTULO_TIPO_CONTA[t]}
52	          </option>
53	        ))}
54	      </CampoSelect>
55	      <CampoTexto
56	        label="Saldo inicial"
57	        value={saldo}
58	        onChange={(e) => setSaldo(e.target.value)}
59	        erro={erros.saldo}
60	        inputMode="decimal"
61	        placeholder="0,00"
62	        dica="Aceita valores negativos, como -50,00."
63	      />
64	      {tipo === 'cartao' ? (
65	        <fieldset className="grid gap-3 sm:col-span-3 sm:grid-cols-3">
66	          <legend className="mb-1 text-sm font-medium text-slate-700">Ciclo do cartão (opcional, preencha tudo ou nada)</legend>
67	          <CampoTexto label="Dia de fechamento" value={fechamento} onChange={(e) => setFechamento(e.target.value)} erro={erros.diaFechamento} inputMode="numeric" placeholder="1 a 28" />
68	          <CampoTexto label="Dia de vencimento" value={vencimento} onChange={(e) => setVencimento(e.target.value)} erro={erros.diaVencimento} inputMode="numeric" placeholder="1 a 28" />
69	          <CampoTexto label="Limite do cartão" value={limite} onChange={(e) => setLimite(e.target.value)} erro={erros.limite} inputMode="decimal" placeholder="0,00" />
70	        </fieldset>
71	      ) : null}
72	      {erros.geral ? (
73	        <div className="sm:col-span-3">
74	          <Alerta>{erros.geral}</Alerta>
75	        </div>
76	      ) : null}
77	      <div className="flex gap-2 sm:col-span-3">
78	        <Botao type="submit">{inicial ? 'Salvar alterações' : 'Criar conta'}</Botao>
79	        <Botao variante="secundario" onClick={onCancelar}>
80	          Cancelar
81	        </Botao>
82	      </div>
83	    </form>
84	  );
85	}
