23	  const [categoriaId, setCategoriaId] = useState(inicial?.categoriaId ?? '');
24	  const [valor, setValor] = useState(inicial ? valorParaCampo(inicial.valor) : '');
25	  const [data, setData] = useState(inicial?.data ?? hojeISO());
26	  const [descricao, setDescricao] = useState(inicial?.descricao ?? '');
27	  const [tags, setTags] = useState(formatarTags(inicial?.tags));
28	  const [erros, setErros] = useState<Erros>({});
29	
30	  if (contasDisponiveis.length === 0) {
31	    return (
32	      <Alerta tipo="aviso">
33	        Você precisa de ao menos uma conta ativa para registrar transações.{' '}
34	        <Link to="/contas" className="font-medium underline">
35	          Criar uma conta
36	        </Link>
37	      </Alerta>
38	    );
39	  }
40	
41	  const categorias = estado.categorias.filter((c) => c.tipo === tipo && (!c.arquivada || c.id === inicial?.categoriaId));
42	
43	  const trocarTipo = (novo: TipoMovimento) => {
44	    setTipo(novo);
45	    setCategoriaId('');
46	  };
47	
48	  const enviar = (e: FormEvent) => {
49	    e.preventDefault();
50	    const centavos = parseValor(valor);
51	    if (centavos === null) {
52	      setErros({ valor: 'Informe um valor válido, como 49,90.' });
53	      return;
54	    }
55	    const r = onSalvar({ contaId, categoriaId, tipo, valor: centavos, data, descricao, tags: parseTags(tags) });
56	    if (!r.ok) setErros(r.campo ? { [r.campo]: r.erro } : { geral: r.erro });
57	  };
58	
59	  return (
60	    <form onSubmit={enviar} noValidate aria-label={inicial ? 'Editar transação' : 'Nova transação'} className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
61	      <CampoSelect label="Tipo" value={tipo} onChange={(e) => trocarTipo(e.target.value as TipoMovimento)}>
62	        <option value="despesa">Despesa</option>
63	        <option value="receita">Receita</option>
64	      </CampoSelect>
65	      <CampoSelect label="Conta" value={contaId} onChange={(e) => setContaId(e.target.value)} erro={erros.contaId}>
66	        {contasDisponiveis.map((c) => (
67	          <option key={c.id} value={c.id}>
68	            {c.nome}
69	          </option>
70	        ))}
71	      </CampoSelect>
72	      <CampoSelect label="Categoria" value={categoriaId} onChange={(e) => setCategoriaId(e.target.value)} erro={erros.categoriaId}>
73	        <option value="">Selecione…</option>
74	        {categorias.map((c) => (
75	          <option key={c.id} value={c.id}>
76	            {c.nome}
77	            {c.arquivada ? ' (arquivada)' : ''}
78	          </option>
79	        ))}
80	      </CampoSelect>
81	      <CampoTexto label="Valor" value={valor} onChange={(e) => setValor(e.target.value)} erro={erros.valor} inputMode="decimal" placeholder="0,00" />
82	      <CampoTexto label="Data" type="date" value={data} onChange={(e) => setData(e.target.value)} erro={erros.data} />
83	      <CampoTexto label="Descrição" value={descricao} onChange={(e) => setDescricao(e.target.value)} erro={erros.descricao} maxLength={140} autoComplete="off" />
84	      <CampoTexto
85	        label="Tags"
86	        value={tags}
87	        onChange={(e) => setTags(e.target.value)}
88	        erro={erros.tags}
89	        dica={`Opcional, separadas por vírgula (até ${TAGS_MAX}, ${TAG_TAMANHO_MAX} caracteres cada).`}
90	        autoComplete="off"
91	      />
92	      {erros.geral ? (
93	        <div className="sm:col-span-2 lg:col-span-3">
94	          <Alerta>{erros.geral}</Alerta>
95	        </div>
96	      ) : null}
97	      <div className="flex gap-2 sm:col-span-2 lg:col-span-3">
98	        <Botao type="submit">{inicial ? 'Salvar alterações' : 'Adicionar transação'}</Botao>
99	        <Botao variante="secundario" onClick={onCancelar}>
100	          Cancelar
101	        </Botao>
102	      </div>
103	    </form>
104	  );
105	}
